"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limits_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _check_graph(changes, applied):
    """Reject unknown references and cycles in the change graph."""
    known = {change["id"] for change in changes}
    for change in changes:
        if change["depends_on"] - known:
            return "unknown-dependency"
    if applied - known:
        return "unknown-dependency"
    if _has_cycle(changes):
        return "dependency-cycle"
    return None


def _has_cycle(changes):
    waiting = {change["id"]: len(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    visited = 0
    while ready:
        change_id = heapq.heappop(ready)
        visited += 1
        for dependent in dependents[change_id]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(ready, dependent)
    return visited != len(changes)


def _topological_order(changes):
    """Deterministic topological order, lexicographic among eligible IDs."""
    waiting = {change["id"]: len(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(ready, dependent)
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limits_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    problem = _check_graph(changes, applied)
    if problem is not None:
        return failure(problem)
    by_id = {change["id"]: change for change in changes}
    order = _topological_order(changes)
    if action == "rollback":
        actions = [change_id for change_id in reversed(order) if change_id in applied]
        units = sum(by_id[change_id]["units"] for change_id in actions)
        return {"status": "ok", "actions": actions, "units": units}
    actions = [change_id for change_id in order if change_id not in applied]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

