"""Normalize release records at the input boundary.

Validates change records and the caller-supplied release journal, collapses
identical duplicate records, rejects conflicting duplicate IDs, validates the
rollback retain list, and exposes the change set, applied set and retain set in
canonical form (sorted dependencies).
"""


class JournalError(ValueError):
    pass


def _invalid():
    raise JournalError("invalid-change")


def _is_id(value):
    return isinstance(value, str) and value != ""


def _read_depends_on(row):
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        _invalid()
    for dep in depends_on:
        if not _is_id(dep):
            _invalid()
    return frozenset(depends_on)


def _read_applied(value):
    if not isinstance(value, list):
        _invalid()
    applied = set()
    for entry in value:
        if not _is_id(entry):
            _invalid()
        applied.add(entry)
    return frozenset(applied)


CHANGE_FIELDS = frozenset({"id", "component", "units", "depends_on", "applied"})


def _only_known_fields(row):
    for key in row:
        if not isinstance(key, str) or key not in CHANGE_FIELDS:
            return False
    return True


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if not isinstance(row, dict) or not _only_known_fields(row):
            _invalid()
        if (not _is_id(row.get("id"))
                or not isinstance(row.get("component"), str) or not row.get("component")
                or type(row.get("units")) is not int or row.get("units") < 1):
            _invalid()
        change_id = row["id"]
        unit_count = row["units"]
        component = row["component"]
        depends_on = _read_depends_on(row)
        if "applied" in row:
            _read_applied(row["applied"])
        existing = changes.get(change_id)
        if existing is None:
            changes[change_id] = {
                "id": change_id,
                "component": component,
                "units": unit_count,
                "depends_on": depends_on,
            }
            continue
        if (existing["component"] != component or existing["units"] != unit_count
                or existing["depends_on"] != depends_on):
            raise JournalError("conflicting-change")
    return sorted(changes.values(), key=lambda change: change["id"])


def read_applied(records):
    """Return the persisted release journal: the set of applied change IDs."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    applied = set()
    for entry in records:
        if not _is_id(entry):
            _invalid()
        applied.add(entry)
    return frozenset(applied)


def read_retain(value, applied):
    """Return the staging rollback retain set.

    ``retain`` defaults to empty and may only name change IDs that are already
    applied. Malformed lists or nonapplied IDs raise ``invalid-retain``.
    """
    if not isinstance(value, list):
        raise JournalError("invalid-retain")
