"""Compose policy, journal and graph data into a plan or a rollback."""
import heapq

from journal import APPLIED_KEY, JournalError, read_applied, read_changes
from policy import PolicyError, check_request, enforce_budget


def failure(code):
    """The single error shape; no partial actions are ever emitted."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes, applied):
    """Validate dependencies against the table and return id -> dependencies.

    Dependencies on changes already applied still have to name a known change:
    the caller's persisted journal and change list describe the same release,
    so an ID missing from either is unknown-dependency rather than something to
    silently drop.
    """
    known = {row["id"] for row in changes}
    graph = {}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
        graph[row["id"]] = list(row["depends_on"])
    for applied_id in applied:
        if applied_id not in known:
            raise JournalError("unknown-dependency")
    return graph


def topological_order(graph):
    """Deterministic topological order, lexicographically smallest id first.

    The heap is the tie-breaker: among all currently eligible changes the
    smallest ID goes first, so the same request always yields the same order
    regardless of input record order. Remaining nodes after draining the heap
    mean a cycle (possibly only among nodes blocked by one), reported as
    dependency-cycle rather than a partial order.
    """
    indegree = {node: len(deps) for node, deps in graph.items()}
    dependents = {node: [] for node in graph}
    for node, deps in graph.items():
        for dependency in deps:
            dependents[dependency].append(node)
    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(graph):
        raise JournalError("dependency-cycle")
    return order


def select_actions(action, order, applied):
    """Pick the emitted subset; the full order is computed either way.

    `plan` walks the deterministic order forward and keeps unapplied changes:
    their dependencies are either unapplied (earlier in the order) or already
    satisfied by `applied`, which is why applied entries never need budget.
    `rollback` walks the same order backwards and keeps applied changes, so
    dependents are reverted before the changes they need.
    """
    if action == "plan":
        return [node for node in order if node not in applied]
    return [node for node in reversed(order) if node in applied]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Order matters: policy (environment/action/budget) is judged before
        # any change or journal content, and budget excess last.
        action, budget = check_request(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get(APPLIED_KEY))
        graph = build_graph(changes, applied)
        order = topological_order(graph)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {row["id"]: row["units"] for row in changes}
    actions = select_actions(action, order, applied)
    units = sum(units_by_id[change_id] for change_id in actions)
    try:
        # Checked only after replay/deduplication, so applied entries and
        # collapsed duplicates never consume the caller's budget.
        enforce_budget(action, units, budget)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

