"""JSON transport for the release planner: one JSON in, one JSON out.

This is the only module that touches stdin/stdout. It never lets an exception
reach the interpreter: every path prints exactly one JSON object and exits 0,
so a malformed request is still a well-formed answer for the caller.
"""
import json
import sys

from planner import plan


def _failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def main():
    try:
        request = json.load(sys.stdin)
