        # Covers malformed JSON; invalid UTF-8 bytes on stdin are handled by the
        # next clause because they surface while reading, not while parsing.
        # All responses still exit 0 with one JSON object: transport errors are
        # answers, not crashes.
        result = _failure("invalid-json")
    except UnicodeDecodeError:
        result = _failure("invalid-json")
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

