"""Compose policy, journal and graph data into a plan or a rollback."""
import heapq

from journal import APPLIED_KEY, JournalError, read_applied, read_changes
from policy import PolicyError, check_request, enforce_budget

RETAIN_KEY = "retain"


def failure(code):
    """The single error shape; no partial actions are ever emitted."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes, applied):
    """Validate dependencies against the table and return id -> dependencies.

    Dependencies on changes already applied still have to name a known change:
    the caller's persisted journal and change list describe the same release,
    so an ID missing from either is unknown-dependency rather than something to
    silently drop.
    """
    known = {row["id"] for row in changes}
    graph = {}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
        graph[row["id"]] = list(row["depends_on"])
    for applied_id in applied:
        if applied_id not in known:
            raise JournalError("unknown-dependency")
    return graph


def topological_order(graph):
    """Deterministic topological order, lexicographically smallest id first.

    The heap is the tie-breaker: among all currently eligible changes the
    smallest ID goes first, so the same request always yields the same order
    regardless of input record order. Remaining nodes after draining the heap
    mean a cycle (possibly only among nodes blocked by one), reported as
    dependency-cycle rather than a partial order.
    """
    indegree = {node: len(deps) for node, deps in graph.items()}
    dependents = {node: [] for node in graph}
    for node, deps in graph.items():
        for dependency in deps:
            dependents[dependency].append(node)
    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(graph):
        raise JournalError("dependency-cycle")
    return order


def select_actions(action, order, applied, retained=frozenset()):
    """Pick the emitted subset; the full order is computed either way.

    `plan` walks the deterministic order forward and keeps unapplied changes:
    their dependencies are either unapplied (earlier in the order) or already
    satisfied by `applied`, which is why applied entries never need budget.
    `rollback` walks the same order backwards and keeps applied changes, so
    dependents are reverted before the changes they need; applied changes in the
    retained closure (the caller's keep-list plus what it depends on) are skipped
    so they stay installed. Skipping them cannot pull a dependency out of the
    rollback set: the retained closure is dependency-closed, so any applied
    change it excludes has no retained (and therefore no surviving) dependent.
    """
    if action == "plan":
        return [node for node in order if node not in applied]
    return [node for node in reversed(order)
            if node in applied and node not in retained]


def retention_closure(retained, graph, applied):
    """Grow the retained set with the applied dependencies those IDs require.

    A retained change stays installed, so whatever it needs to run must stay too;
    dependencies point backwards, so we follow `depends_on` from each retained ID.
    Only applied nodes are collected: a dependency that was never applied was
    never removed and needs no retaining. The graph is already known to be
    acyclic and closed, so the stack terminates; `kept` also keeps it linear when
    many retained IDs share dependencies.
    """
    kept = set(retained)
    stack = list(retained)
    while stack:
        node = stack.pop()
        for dependency in graph[node]:
            if dependency in applied and dependency not in kept:
                kept.add(dependency)
                stack.append(dependency)
    return kept


def read_retain(request, action, applied):
    """Resolve the G2 `retain` list for a rollback into a set of kept IDs.

    `retain` is rollback-only: for a plan it is ignored entirely, so a forward
    request never changes meaning because of a leftover field. For rollback the
    value defaults to empty and must be a list of non-empty ID strings; each ID
    must also be in `applied` (a change that is not applied has nothing to keep
    in place, and the caller's journal is likely stale). Both mistakes are
    invalid-retain. This runs after the graph, so `applied` already only holds
    known IDs and the membership test cannot confuse "unknown" with "not applied".
    """
    if action != "rollback":
        return set()
    value = request.get(RETAIN_KEY)
    if value is None:
        return set()
    if not isinstance(value, list):
        raise JournalError("invalid-retain")
    retained = set()
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
        if item not in applied:
            raise JournalError("invalid-retain")
        retained.add(item)
    return retained


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Order matters: policy (environment/action/budget) is judged before
        # any change or journal content, and budget excess last.
        action, budget = check_request(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get(APPLIED_KEY))
        graph = build_graph(changes, applied)
        order = topological_order(graph)
        # After the graph: applied IDs are known to exist, so a retain ID that is
        # unknown is reported with retain semantics, not unknown-dependency.
