"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _identifier(value):
    return isinstance(value, str) and bool(value)


def _read_id_list(value):
    if not isinstance(value, list) or not all(_identifier(item) for item in value):
        raise JournalError("invalid-change")
    return frozenset(value)


def read_changes(records):
    """Validate change records and collapse identical duplicate IDs.

    Equality covers id, component, units and the set of dependencies; records
    sharing an ID but differing in any of those conflict.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not _identifier(row.get("id"))
                or not _identifier(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        record = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_id_list(row.get("depends_on", [])),
        }
        seen = changes.get(record["id"])
        if seen is None:
            changes[record["id"]] = record
        elif seen != record:
            raise JournalError("conflicting-change")
    return [changes[key] for key in sorted(changes)]


def read_applied(applied, changes):
    """Validate the persisted journal against the known change IDs."""
    known = {row["id"] for row in changes}
    ids = _read_id_list([] if applied is None else applied)
    if not ids <= known:
        raise JournalError("unknown-dependency")
    return ids

