    """Topological order with lexicographic tie-breaking among eligible IDs."""
    known = {row["id"] for row in changes}
    indegree = {}
    children = {row["id"]: [] for row in changes}
    for row in changes:
        indegree[row["id"]] = len(row["depends_on"])
        for target in row["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
            children[target].append(row["id"])
    ready = [key for key, count in indegree.items() if not count]
    heapq.heapify(ready)
    order = []
    while ready:
        key = heapq.heappop(ready)
        order.append(key)
        for child in children[key]:
            indegree[child] -= 1
            if not indegree[child]:
                heapq.heappush(ready, child)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def _retained(changes, applied, retain):
    """Return `retain` plus every applied dependency it transitively requires."""
    depends_on = {row["id"]: row["depends_on"] for row in changes}
    kept = set()
    pending = list(retain)
    while pending:
        key = pending.pop()
        if key in kept:
            continue
        kept.add(key)
        # Only applied dependencies are kept: an unstaged dependency cannot be
        # left installed by a rollback of applied changes.
        pending.extend(target for target in depends_on[key] if target in applied)
    return kept


def _compose(action, budget, changes, order, applied, retain):
    units_by_id = {row["id"]: row["units"] for row in changes}
    if action == "plan":
        emitted = [key for key in order if key not in applied]
        units = sum(units_by_id[key] for key in emitted)
        if units > budget:
            return failure("budget-exceeded")
    else:
        kept = _retained(changes, applied, retain)
        emitted = [key for key in reversed(order) if key in applied and key not in kept]
        units = sum(units_by_id[key] for key in emitted)
    return {"status": "ok", "actions": emitted, "units": units}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"), changes)
        order = topo_order(changes)
        retain = read_retain(request.get("retain"), applied) if request["action"] == "rollback" else frozenset()
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return _compose(request["action"], budget, changes, order, applied, retain)

