"""Compose policy and journal data into ordered actions and a JSON result.

Import direction is fixed: planner -> policy, planner -> journal. This is the
only module that assembles the ok/error objects, so the entrypoint never has
to decide status and no failure path can leak partial actions.
"""
import heapq

from journal import JournalError, check_dependencies, read_applied, read_changes
from policy import PolicyError, authorize, check_budget


class PlanError(Exception):
    """Graph-level failure code (`dependency-cycle`)."""


def failure(code):
    """Exact SPEC failure shape; actions stay empty on every error path."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Full dependency order, lexicographically smallest eligible id first.

    A min-heap over currently eligible ids gives the SPEC tie-break without
    relying on input order, so the same request always yields the same order.
    If fewer ids are emitted than exist, some nodes were never eligible and
    the remainder is a cycle (run only after dependency targets are known to
    exist, otherwise a dangling edge would be misreported as a cycle).
    """
    by_id = {row["id"]: row for row in changes}
    waiting = {row["id"]: len(row["depends_on"]) for row in changes}
    dependents = {change_id: [] for change_id in by_id}
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].append(row["id"])
    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for child in dependents[change_id]:
            waiting[child] -= 1
            if waiting[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(by_id):
        # Everything involved in or blocked behind a cycle stays unordered.
        raise PlanError("dependency-cycle")
    return order


def select_actions(action, order, applied):
    """Pick emitted ids for the action, preserving deterministic order.

    `plan` walks forward over unapplied changes only: already applied entries
    already satisfied their dependencies and must not consume budget again.
    `rollback` walks the reverse of the *full* order and keeps only applied
    items, so rolled-back ids unwind in the opposite order of their release.
    """
    if action == "rollback":
        return [change_id for change_id in reversed(order) if change_id in applied]
    return [change_id for change_id in order if change_id not in applied]


def plan(request):
    """Validate, order, and return exactly one ok/error object.

    Step order is the documented error precedence: request shape -> policy
    (environment, action, budget) -> journal (fields, replay, dependencies,
    journal IDs) -> graph (cycle) -> budget cap. Budget is checked last and
    against emitted units only, so it can never mask a domain error and no
    partial action list is ever returned.
    """
    if not isinstance(request, dict):
        return failure("invalid-request")
